<?php
declare(strict_types=1);
namespace OCA\ReinhardtERP\Service;
use OCA\ReinhardtERP\Service\DocumentInboxService;
use OCA\ReinhardtERP\Service\FolderService;
final class FinanceExportService {
 public function __construct(private DocumentInboxService $documents,private FolderService $folders){}
 public function export(array $filters=[]):array{
  $rows=$this->documents->financeRows($filters);if($rows===[])throw new \RuntimeException('Für die gewählten Filter sind keine Belege vorhanden.');
  $labels=['incoming_invoice'=>'Eingangsrechnungen','outgoing_invoice'=>'Ausgangsrechnungen','bank_statement'=>'Kontoauszuege','cash'=>'Kasse','tax'=>'Steuern','credit_note'=>'Gutschriften','accounting_other'=>'Sonstige_Belege'];
  $csv=fopen('php://temp','w+');if($csv===false)throw new \RuntimeException('Belegübersicht konnte nicht erstellt werden.');fwrite($csv,"\xEF\xBB\xBF");fputcsv($csv,['Belegart','Belegdatum','Belegnummer','Lieferant','Kunde','Projekt','Netto','MwSt','Brutto','Waehrung','Datei'],';');
  $entries=[];$used=[];foreach($rows as $row){$actual=(string)($row['document_type']??'unassigned');$type=$actual!=='unassigned'?$actual:(string)($row['suggested_type']??'unassigned');$folder=$labels[$type]??'Sonstige_Belege';$path=(string)($row['file_path']??'');try{$file=$this->folders->readFile($path);$content=(string)($file['content']??'');}catch(\Throwable){continue;}$name=$this->exportFileName((string)($row['file_name']??$row['original_name']??'Beleg.pdf'));$zipName=$folder.'/'.$name;$n=2;while(isset($used[$zipName])){$pi=pathinfo($name);$stem=(string)($pi['filename']??'Beleg');$ext=isset($pi['extension'])&&$pi['extension']!==''?'.'.$pi['extension']:'';$zipName=$folder.'/'.$stem.'_'.$n.$ext;$n++;}$used[$zipName]=true;$entries[$zipName]=$content;fputcsv($csv,[$folder,(string)($row['document_date']??$row['suggested_document_date']??''),(string)($row['document_no']??$row['suggested_document_no']??''),(string)($row['supplier_name']??''),(string)($row['customer_name']??''),trim((string)($row['project_no']??'').' '.(string)($row['project_title']??'')),(string)($row['net_amount']??''),(string)($row['vat_amount']??''),(string)($row['gross_amount']??''),(string)($row['currency']??'EUR'),$zipName],';');}
  if($entries===[]){fclose($csv);throw new \RuntimeException('Die ausgewählten Belegdateien konnten nicht gelesen werden.');}rewind($csv);$entries['Beleguebersicht.csv']=(string)stream_get_contents($csv);fclose($csv);$period=(string)($filters['year']??'');if($period==='')$period='Auswahl';if((string)($filters['month']??'')!=='')$period.='-'.str_pad((string)$filters['month'],2,'0',STR_PAD_LEFT);return ['name'=>'Betrio-Steuerbuero-'.$this->safe($period).'.zip','content'=>$this->buildPortableZip($entries)];
 }
 private function buildPortableZip(array $entries):string{$body='';$central='';$offset=0;$count=0;foreach($entries as $name=>$content){$name=str_replace('\\','/',ltrim((string)$name,'/'));$content=(string)$content;$size=strlen($content);$crc=(int)sprintf('%u',crc32($content));$nameLen=strlen($name);$local=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,0,$crc,$size,$size,$nameLen,0).$name.$content;$body.=$local;$central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,0,$crc,$size,$size,$nameLen,0,0,0,0,0,$offset).$name;$offset+=strlen($local);$count++;}return $body.$central.pack('VvvvvVVv',0x06054b50,0,0,$count,$count,strlen($central),strlen($body),0);}
 private function exportFileName(string $name):string{$name=basename(trim($name));$name=preg_replace('/[\\x00-\\x1F\\x7F<>:"\\/\\\\|?*]+/u','_',$name)??'Beleg';$name=trim($name," .\t\n\r\0\x0B");return $name!==''?$name:'Beleg';}
 private function safe(string $value):string{$value=preg_replace('/[^A-Za-z0-9._-]+/','_',trim($value))??'';return trim($value,'_.-')?:'Auswahl';}
}
